35:   const [text, setText] = useState("");
36:   const [scope, setScope] = useState("Build the approved plan in the isolated demo workspace and leave a passing Node test.");
37:   const [change, setChange] = useState("");
38:   const [busy, setBusy] = useState(false);
39:   const [slow, setSlow] = useState(false);
40:   const [error, setError] = useState<string | null>(null);
41:   const [exportNote, setExportNote] = useState<string | null>(null);
42:   const [setupOpen, setSetupOpen] = useState(false);
43:   const [onboardingDismissed, setOnboardingDismissed] = useState(false);
44:   const reduceMotion = useReducedMotion();
45: 
46:   useEffect(() => {
47:     void Promise.all([loadProject(), loadConnection()])
48:       .then(([loaded, native]) => {
49:         setProject(loaded);
50:         setConnection(native);
51:       })
52:       .catch((caught: unknown) => {
53:         setError(caught instanceof Error ? caught.message : "The workshop could not be loaded.");
54:       });
55:   }, []);
56: 
57:   const activeRun = useMemo(
58:     () => project?.operations.find((operation) => operation.status === "RUNNING" || operation.status === "QUEUED") ?? null,
59:     [project],
60:   );
61: 
62:   useEffect(() => {
63:     if (!activeRun) return;
64:     const timer = window.setInterval(() => {
65:       void loadProject().then(setProject).catch(() => {
66:         // A transient poll failure must not replace the visible project state.
67:       });
68:     }, 1_500);
69:     return () => window.clearInterval(timer);
70:   }, [activeRun?.id]);
71: 
72:   async function act(work: () => Promise<{ project: WorkshopProject }>) {
73:     setBusy(true);
74:     setSlow(false);
75:     setError(null);
76:     const timer = window.setTimeout(() => setSlow(true), 8_000);
77:     try {
78:       const result = await work();
79:       setProject(result.project);
80:     } catch (caught) {
81:       const loaded = await loadProject().catch(() => null);
82:       if (loaded) setProject(loaded);
83:       setError(caught instanceof ApiError
84:         ? `${caught.message} ${caught.retryable ? "You can try a new request. The current section was not overwritten." : "Nothing was repeated."}`
85:         : "The workshop lost its connection. Reload before trying again.");
86:     } finally {
87:       window.clearTimeout(timer);
88:       setBusy(false);
89:       setSlow(false);
90:     }
91:   }
92: 
93:   if (!project || !connection) {
94:     return (
95:       <div className="workshop-shell">
96:         <WorkshopHeader connection={connection} onSetup={() => setSetupOpen(true)} />
97:         <main className="workshop-loading">
