102:           {error ? <button className="action secondary" type="button" onClick={() => window.location.reload()}>Reload the workshop</button> : null}
103:         </main>
104:       </div>
105:     );
106:   }
107: 
108:   const section = project.sections.find((item) => item.id === project.currentSectionId) ?? null;
109:   const abandoned = project.operations.find((item) => item.status === "ABANDONED") ?? null;
110:   const profile = stageSpirit(project.stage);
111:   const characterState = spiritStateFor(project, section);
112:   const approved = project.sections.filter((item) => item.status === "APPROVED").length;
113:   const selectedModel = findSelectedModel(connection.discovery, project.engine.model);
114:   const hostedDemo = connection.deploymentMode === "hosted-demo";
115:   const firstRun = !connection.discovery || !project.engine.model;
116:   const showOnboarding = !hostedDemo && (setupOpen || (firstRun && !onboardingDismissed && connection.state !== "unavailable"));
117:   const connected = connection.state === "connected" || connection.state === "degraded";
118:   const header = project.stage === "ORACLE"
119:     ? "What's still haunting your to-do list?"
120:     : section
121:       ? `${section.title} — section ${section.order} of ${project.sections.length}`
122:       : project.nextAction;
123: 
124:   if (showOnboarding) {
125:     return (
126:       <div className="workshop-shell">
127:         <WorkshopHeader connection={connection} onSetup={() => setSetupOpen(true)} />
128:         <main className="workshop workshop-onboarding">
129:           <Onboarding
130:             connection={connection}
131:             project={project}
132:             firstRun={firstRun}
133:             onConnection={(status) => {
134:               setConnection(status);
135:               if (status.discovery && project.engine.model) setSetupOpen(false);
136:             }}
