378: function WorkshopHeader({ connection, onSetup }: { connection: ConnectionStatus | null; onSetup: () => void }) {
379:   const state = connection?.state;
380:   const live = state === "connected";
381:   const warn = state === "degraded" || state === "checking";
382:   return (
383:     <header className="workshop-header">
384:       <div className="workshop-header-inner">
385:         <Brand compact />
386:         <div className="workshop-header-actions">
387:           <a href="/">Overview</a>
388:           <a href="/demo">Demo</a>
389:           <button className="engine-pill" type="button" onClick={onSetup} aria-label="Open OpenCode connection setup">
390:             <span className={live ? "engine-dot is-live" : warn ? "engine-dot is-warn" : "engine-dot"} aria-hidden="true" />
391:             {connection ? connectionLabel(state) : "Checking OpenCode"}
392:           </button>
393:         </div>
394:       </div>
395:     </header>
396:   );
397: }
398: 
399: function connectionLabel(state: ConnectionStatus["state"] | undefined): string {
400:   if (!state) return "Checking OpenCode";
401:   if (state === "connected") return "OpenCode connected";
402:   if (state === "degraded") return "OpenCode warnings";
403:   if (state === "authentication_required") return "OpenCode auth required";
404:   if (state === "incompatible_version") return "OpenCode incompatible";
405:   if (state === "not_configured") return "OpenCode not configured";
406:   if (state === "checking") return "Checking OpenCode";
407:   return "OpenCode unreachable";
408: }
