495:       diagnostics.push({
496:         code: "PROVIDER_NOT_CONNECTED",
497:         severity: "warning",
498:         title: `${provider.name} needs authentication`,
499:         message: provider.detail,
500:         repair: `Connect ${provider.name} inside OpenCode with /connect, or choose a model from a provider that is already available.`,
501:       });
502:     }
503:     if (selected) {
504:       const match = discovery.models.find((model) => model.providerID === selected.providerID && model.id === selected.id);
505:       if (!match) {
506:         diagnostics.push({
507:           code: "MODEL_UNAVAILABLE",
508:           severity: "error",
509:           title: "Selected model is unavailable",
510:           message: `${selected.providerID}/${selected.id} is not in the current OpenCode catalog.`,
511:           repair: "Choose another model in the OpenCode panel. The previous selection was not replaced automatically.",
512:         });
513:       } else if (match.availability !== "available") {
514:         diagnostics.push({
515:           code: "MODEL_DISABLED",
516:           severity: "error",
517:           title: "Selected model is disabled",
518:           message: `${match.name} is present but unavailable (${match.status}).`,
519:           repair: "Enable the model or provider inside OpenCode, or choose another model.",
520:         });
521:       } else if (!modelAllowed(match, accessMode)) {
522:         diagnostics.push({
