:root {
  color-scheme: dark;

  /* Foundation */
  --ink-0: #05070d;
  --ink-1: #090d17;
  --ink-2: #0e1422;
  --ink-3: #141c2f;
  --ink-4: #1b2540;
  --paper: #f0ebe1;
  --paper-soft: #ded7c9;

  /* Light */
  --amber: #f3b66d;
  --amber-bright: #ffd08a;
  --amber-deep: #b97935;
  --amber-ink: #24170a;
  --violet: #b9a4ff;
  --violet-deep: #6d5bd0;
  --spectral: #8ba4ff;
  --cyan: #9fe7ff;
  --mint: #8fe3b8;
  --rose: #ffb4a8;

  /* Text */
  --text: #f4f1e9;
  --text-muted: #b8b3c7;
  --text-dim: #8d88a0;
  --text-ink: #141018;

  /* Surfaces */
  --surface-1: rgb(14 20 34 / 82%);
  --surface-2: rgb(20 28 47 / 78%);
  --surface-3: rgb(27 37 64 / 72%);
  --surface-paper: rgb(240 235 225 / 7%);
  --surface-terminal: #070b12;

  /* Borders */
  --border: rgb(226 222 255 / 13%);
  --border-strong: rgb(226 222 255 / 26%);
  --border-amber: rgb(243 182 109 / 42%);
  --border-violet: rgb(185 164 255 / 38%);

  /* Status */
  --status-positive: #8fe3b8;
  --status-active: #9fe7ff;
  --status-warning: #ffd08a;
  --status-danger: #ffb4a8;
  --status-neutral: #b8b3c7;

  /* Compatibility aliases used by the OpenCode onboarding/advanced panel. */
  --bg: var(--ink-0);
  --surface: var(--ink-2);
  --raised: var(--ink-3);
  --accent: var(--amber);
  --success: var(--status-positive);
  --danger: var(--status-danger);
  --muted: var(--text-muted);

  /* Focus */
  --focus: #ffd08a;
  --focus-halo: rgb(255 208 138 / 28%);

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;
  --space-7: 3rem;
  --space-8: 4rem;
  --space-9: 6rem;

  /* Radius */
  --radius-xs: 6px;
  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --radius-pill: 999px;

  /* Elevation */
  --shadow-1: 0 1px 0 rgb(255 255 255 / 5%) inset, 0 8px 24px rgb(0 0 0 / 18%);
  --shadow-2: 0 1px 0 rgb(255 255 255 / 7%) inset, 0 18px 48px rgb(0 0 0 / 32%);
  --shadow-3: 0 1px 0 rgb(255 255 255 / 8%) inset, 0 32px 90px rgb(0 0 0 / 45%);
  --glow-amber: 0 0 40px rgb(243 182 109 / 18%);
  --glow-violet: 0 0 44px rgb(139 164 255 / 18%);

  /* Type */
  --font-display: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --font-ui: "Avenir Next", Avenir, "Segoe UI", Inter, system-ui, -apple-system, sans-serif;
  --font-mono: "SFMono-Regular", "Cascadia Code", "Roboto Mono", ui-monospace, monospace;
  --leading-tight: 1.02;
  --leading-snug: 1.2;
  --leading-body: 1.65;

  /* Motion */
  --dur-instant: 80ms;
  --dur-fast: 140ms;
  --dur-base: 240ms;
  --dur-slow: 520ms;
  --ease-standard: cubic-bezier(0.2, 0.7, 0.2, 1);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
}

