91: /**
92:  * Validates the OpenCode server address accepted by this application.
93:  *
94:  * Local deployments may use loopback HTTP because the connection never leaves
95:  * the machine. Any non-loopback address must use HTTPS; the network policy
96:  * additionally requires an explicit host allowlist and blocks private and
97:  * metadata addresses unless separately configured.
98:  */
99: export function validateServerUrl(raw: string): ValidatedServerUrl {
100:   const input = raw.trim();
101:   if (!input) throw new ConnectionConfigError("Enter an OpenCode server URL.", "INVALID_URL");
102:   let parsed: URL;
103:   try {
104:     parsed = new URL(input);
105:   } catch {
106:     throw new ConnectionConfigError("The OpenCode server URL is not a valid absolute URL.", "INVALID_URL");
107:   }
108:   if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
109:     throw new ConnectionConfigError("Only http:// (loopback) and https:// OpenCode URLs are supported.", "UNSUPPORTED_SCHEME");
110:   }
111:   if (parsed.username || parsed.password) {
112:     throw new ConnectionConfigError("Do not put credentials in the server URL. Enter the OpenCode password separately.", "URL_CREDENTIALS_FORBIDDEN");
113:   }
114:   if (parsed.search || parsed.hash) {
115:     throw new ConnectionConfigError("The OpenCode server URL must not include a query string or fragment.", "INVALID_URL");
116:   }
117:   const hostname = parsed.hostname.replace(/^\[|\]$/g, "").toLowerCase();
118:   const loopback = hostname === "localhost" || hostname === "127.0.0.1" || hostname === "::1" || hostname.startsWith("127.");
119:   if (parsed.protocol === "http:" && !loopback) {
120:     throw new ConnectionConfigError("A non-loopback OpenCode URL requires HTTPS.", "REMOTE_HTTP_FORBIDDEN");
121:   }
122:   parsed.pathname = parsed.pathname.replace(/\/+$/, "");
123:   return { url: parsed.toString().replace(/\/$/, ""), loopback, https: parsed.protocol === "https:" };
124: }
